   (the assembly addresses its own non-preemptible symbols PC-relative). */
{
  global:
    ANativeActivity_onCreate;
    JNI_OnLoad;
    Java_com_aure_totk_GameHold_nativeEnabled;
    Java_com_aure_totk_GameHold_nativeSettingsActive;
    Java_com_aure_totk_GameHold_nativePendingPause;
    Java_com_aure_totk_GameHold_nativeFlushPause;
  local: *;
};
